import{readFileSync,writeFileSync,existsSync}from'node:fs';import{randomUUID,createHash}from'node:crypto';import assert from'node:assert/strict';import{productionEnvironment,productionPsql}from'../scripts/lib/production-database.mjs';import{practiceData,uuidFrom}from'../scripts/lib/capacity-load.mjs';
const out='.verification/targeted-performance-sql-baseline-v2-20261025.json';assert(!existsSync(out));const state=JSON.parse(readFileSync('.verification/targeted-performance-fixture-20261025.json'));assert(state.status==='seeded'&&state.practices===1);const http=JSON.parse(readFileSync('.verification/targeted-performance-http-baseline-20261025.json'));assert(http.status==='complete'&&http.created.length===3);const d=practiceData(1),owner=uuidFrom('capacity-owner-1'),patient=d.patient(http.patientIndex),date=http.date;assert(/^\d{4}-\d{2}-\d{2}$/.test(date));const{database}=productionEnvironment(process.cwd());const q=x=>"'"+String(x).replaceAll("'","''")+"'";const sql=(text,timeout=45000)=>productionPsql(database,text,{application:'cita_suite_targeted_explain',timeout});
const guard=`do $$begin if(select count(*)from public.businesses where id=${q(d.business)}::uuid and slug='capacity-01')<>1 or(select count(*)from public.business_users where business_id=${q(d.business)}::uuid and user_id=${q(owner)}::uuid and role='owner'and status='active')<>1 or(select count(*)from public.patients where business_id=${q(d.business)}::uuid)<>6000 then raise exception 'OWNED_TARGET_GUARD';end if;end$$;`;
const pre=JSON.parse(sql(`begin transaction read only;set local statement_timeout='10s';${guard}select jsonb_build_object('revision',(select revision from private.availability_configuration_versions where business_id=${q(d.business)}::uuid),'appointments',(select count(*)from public.appointments where business_id=${q(d.business)}::uuid),'statementStatsReset',(select stats_reset from extensions.pg_stat_statements_info),'startsAt',(select t from generate_series((${q(date)}::date+time '09:00')at time zone 'America/Argentina/Buenos_Aires',(${q(date)}::date+time '17:30')at time zone 'America/Argentina/Buenos_Aires',interval '30minutes')t where not exists(select 1 from public.appointment_professionals a where a.business_id=${q(d.business)}::uuid and a.professional_id=${q(d.professionals[0])}::uuid and a.status in('reserved','confirmed','reschedule_requested')and a.blocking_starts_at<t+interval '30minutes'and a.blocking_ends_at>t)order by t limit 1));rollback;`));assert(pre.appointments===12003&&typeof pre.startsAt==='string'&&Number.isSafeInteger(pre.revision)&&pre.revision>0);const business=`${q(d.business)}::uuid`,pid=`${q(patient)}::uuid`;
const cases=[['membership_context',`select * from public.list_user_business_contexts()`],['availability_catalog',`select public.get_availability_catalog(${business},false)`],['availability_window_day',`select public.get_availability_window(${business},false,${q(d.services[0])}::uuid,array[${q(d.professionals[0])}::uuid],${q(date)}::date,${q(date)}::date,${pre.revision})`],['availability_window_15d_3professionals',`select public.get_availability_window(${business},false,null,array[${d.professionals.map(p=>q(p)+'::uuid').join(',')}],${q(date)}::date,${q(date)}::date+14,${pre.revision})`],['patient_base',`select id,full_name,dni,phone,email,birth_date,address,insurance,insurance_plan,archived_at,created_at,updated_at from public.patients where id=${pid} and business_id=${business}limit 1`],['patient_clinical_profile',`select allergies,medication,background,custom_fields,updated_at,updated_by from public.patient_clinical_profiles where patient_id=${pid} and business_id=${business}limit 1`],['patient_entries',`select e.id,e.created_at,e.entry_type,e.description,e.teeth,e.internal_note,e.created_by_user_id,e.locked_after,c.amount from public.clinical_entries e left join public.clinical_entry_costs c on c.business_id=e.business_id and c.clinical_entry_id=e.id where e.patient_id=${pid} and e.business_id=${business} and e.archived_at is null order by e.created_at desc,e.id desc limit 31`],['patient_appointments',`select id,starts_at,ends_at,status,source,service_name_snapshot,professional_name_snapshot from public.appointments where patient_id=${pid} and business_id=${business} and status in('reserved','confirmed','reschedule_requested')and starts_at>=statement_timestamp()order by starts_at limit 12`]];
const prefix=`begin transaction read only;set local statement_timeout='10s';set local lock_timeout='2s';${guard}set local request.jwt.claims=${q(JSON.stringify({role:'authenticated',sub:owner}))};set local role authenticated;`;
function block(name,query){assert(/^[a-z0-9_]+$/.test(name));return`select 'PERF_START ${name}';explain(analyze,buffers,timing off,format json)${query};select 'PERF_END';`;}
function parse(raw){return [...raw.matchAll(/PERF_START ([a-z0-9_]+)\n([\s\S]*?)\nPERF_END/g)].map(m=>{const p=JSON.parse(m[2]);assert(Array.isArray(p)&&p.length===1&&typeof p[0]['Execution Time']==='number');return{name:m[1],plan:p[0]};});}
const record={startedAt:new Date().toISOString(),runtime:state.runtime,role:'authenticated owner with request JWT claims; atomic creation service_role with explicit validated actor',pre,scope:'Targeted EXPLAIN ANALYZE over one owned practice. Read probes read-only,3write probes rolled back. Function total times include nested work; nested plans are not fabricated. Patient projection mirrors source but is not claimed as identical to the PostgREST wrapper SQL.',plans:[],status:'running'};const save=()=>writeFileSync(out,JSON.stringify(record,null,2)+'\n',{mode:0o600});save();
try{
 let input=prefix;for(let rep=1;rep<=5;rep++)for(const[name,query]of cases)input+=block(name+'_r'+rep,query);input+='rollback;';record.readSqlSha256=createHash('sha256').update(input).digest('hex');let t=performance.now();const raw=sql(input,75000);record.readClientWallMs=Math.round(performance.now()-t);writeFileSync('.verification/targeted-performance-read-plans-20261025.log',raw,{flag:'wx',mode:0o600});const reads=parse(raw);assert(reads.length===40);record.plans.push(...reads);save();
 const phone='+54911'+String(100000+http.patientIndex).padStart(8,'0');let writeInput='';for(let rep=1;rep<=3;rep++){const rpc=`select * from public.create_appointment_with_patient_identity(p_business_id=>${business},p_patient_mode=>'existing',p_patient_id=>${pid},p_patient_name=>null,p_patient_phone_raw=>${q(phone)},p_patient_phone_e164=>${q(phone)},p_patient_email=>null,p_update_existing_phone=>false,p_owner_id=>${q(owner)}::uuid,p_service_id=>${q(d.services[0])}::uuid,p_professional_ids=>array[${q(d.professionals[0])}::uuid],p_starts_at=>${q(pre.startsAt)}::timestamptz,p_internal_note=>null,p_created_by_user_id=>${q(owner)}::uuid,p_ignore_break=>false,p_source=>'manual',p_phone_communication_status=>'valid',p_phone_warning_acknowledged=>false,p_idempotency_key=>${q(randomUUID())},p_replay_only=>false)`;writeInput+=`begin;set local statement_timeout='10s';set local lock_timeout='2s';${guard}set local request.jwt.claims='{"role":"service_role"}';set local role service_role;`+block('create_appointment_r'+rep,rpc)+'rollback;';}record.writeSqlSha256=createHash('sha256').update(writeInput).digest('hex');t=performance.now();const rawWrite=sql(writeInput,45000);record.writeClientWallMs=Math.round(performance.now()-t);writeFileSync('.verification/targeted-performance-write-plans-20261025.log',rawWrite,{flag:'wx',mode:0o600});const writes=parse(rawWrite);assert(writes.length===3&&writes.every(x=>x.plan.Plan['Actual Rows']===1));record.plans.push(...writes);record.post=JSON.parse(sql(`begin transaction read only;select jsonb_build_object('appointments',(select count(*)from public.appointments where business_id=${business}),'statementStatsReset',(select stats_reset from extensions.pg_stat_statements_info));rollback;`));assert(record.post.appointments===pre.appointments,'ROLLED_BACK_CREATIONS_REMAIN');record.status='complete';record.finishedAt=new Date().toISOString();save();console.log({status:record.status,plans:record.plans.length,ownedWriteProbesRolledBack:true,readClientWallMs:record.readClientWallMs,writeClientWallMs:record.writeClientWallMs});
}catch(e){record.status='failed';record.failure={name:e.name,message:String(e.message).slice(0,180)};save();throw e;}
